import numpy as np,wave
bands=[(30,120),(120,260),(260,500),(500,900),(900,1800),(1800,4000),(4000,8000)]
def sub(wav):
 f=wave.open('/workspace/stem_'+wav+'.wav');sr=f.getframerate();x=np.frombuffer(f.readframes(f.getnframes()),dtype='<i2').reshape(-1,2).mean(axis=1)/32768
 x=x[int(6.4*sr):int(19.2*sr)];m=len(x)//4096;xx=x[:m*4096].reshape(m,4096)*np.hanning(4096);ff=np.fft.rfftfreq(4096,1/sr)
 X=abs(np.fft.rfft(xx,axis=1))**2;energy=[]
 for a,b in bands:energy.append(np.sqrt(X[:,(ff>=a)&(ff<b)].sum(axis=1).mean())/4096)
 return np.array(energy)
for wav in ['drums','bass','keys','arps','lead','bells']:
 s=sub(wav)
 print(f'{wav:6s}',*[f'{20*np.log10(z+1e-9):6.1f}' for z in s])
print('bands',bands)
PY"}

